CREATE TABLE two_factor (user_id TEXT PRIMARY KEY NOT NULL REFERENCES users(user_id), secret TEXT NOT NULL CHECK(length(secret) >= 16), enabled INTEGER NOT NULL DEFAULT 0 CHECK(enabled IN (0,1)), last_step INTEGER, recovery_hashes_json TEXT NOT NULL DEFAULT '[]' CHECK(json_valid(recovery_hashes_json) AND json_type(recovery_hashes_json)='array'), created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
